&lt;&lt;name&gt;&gt;SimpleCalc-sdkClient&lt;&lt;/name&gt;&gt;
&lt;&lt;url&gt;&gt;http://maven.apache.org&lt;&lt;/url&gt;&gt;
&lt;&lt;dependencies&gt;&gt;
&lt;&lt;dependency&gt;&gt;
